    "legal.privacy.s1.title": "1. Quem somos",
    "legal.privacy.s1.p1": "A **{brand}** é uma loja de produtos importados do Japão, operada por **{contact}**, estabelecida em **{address}**. Operamos o site **nikkeybox.jp** e tratamos os dados dos nossos clientes com transparência e responsabilidade, em conformidade com a Lei Geral de Proteção de Dados (LGPD — Lei nº 13.709/2018).",
    "legal.privacy.s1.p2": "Contato do responsável pelos dados: {email}",
    "legal.privacy.s2.title": "2. Quais dados coletamos",
    "legal.privacy.s2.li1": "**Dados de cadastro:** nome, e-mail e senha (armazenada de forma criptografada).",
    "legal.privacy.s2.li2": "**Dados de entrega:** endereço completo, CEP, cidade, estado/prefeitura e telefone de contato.",
