    "legal.privacy.s2.li4": "**Dados de navegação:** páginas visitadas, tempo de sessão e dispositivo — coletados anonimamente via Firebase Analytics, somente após seu consentimento no banner de cookies.",
    "legal.privacy.s2.important": "**Importante:** não coletamos nem armazenamos dados de cartão de crédito em nossos servidores. Pagamentos via PIX e PayPay são processados externamente por plataformas seguras.",
