    "legal.privacy.s4.title": "4. Base legal para o tratamento (LGPD)",
    "legal.privacy.s4.li1": "**Execução de contrato** — para processar compras, pagamentos e entregas.",
    "legal.privacy.s4.li2": "**Consentimento** — para uso de cookies analíticos e comunicações de marketing.",
    "legal.privacy.s4.li3": "**Interesse legítimo** — para prevenção de fraudes e melhorias na plataforma.",
    "legal.privacy.s4.li4": "**Obrigação legal** — para emissão de documentos e registros fiscais.",
    "legal.privacy.s5.title": "5. Compartilhamento de dados",
    "legal.privacy.s5.p1": "Seus dados são compartilhados estritamente com parceiros necessários para a prestação do serviço:",
    "legal.privacy.s5.li1": "**Google Firebase** — banco de dados, autenticação de conta e métricas analíticas. Os servidores seguem padrões internacionais de segurança, e a transferência internacional de dados é amparada por cláusulas contratuais padrão, conforme o art. 33 da LGPD.",
    "legal.privacy.s5.li2": "**Resend** — plataforma técnica para envio de e-mails transacionais (confirmação de pedidos e rastreamento).",
    "legal.privacy.s5.li3": "**Japan Post / Correios / transportadoras** — para a realização da entrega física dos produtos.",
    "legal.privacy.s5.p2": "Jamais vendemos ou comercializamos seus dados pessoais com terceiros.",
    "legal.privacy.s6.title": "6. Seus direitos (LGPD)",
    "legal.privacy.s6.p1": "Como titular dos dados, você pode solicitar a qualquer momento:",
    "legal.privacy.s6.li1": "Confirmar e acessar os dados pessoais que mantemos sobre você.",
    "legal.privacy.s6.li2": "Corrigir dados incompletos, inexatos ou desatualizados.",
    "legal.privacy.s6.li3": "Solicitar a exclusão ou anonimização de seus dados de nossa base.",
    "legal.privacy.s6.li4": "Solicitar a portabilidade dos dados para outro fornecedor.",
    "legal.privacy.s6.li5": "Revogar o consentimento previamente dado para cookies analíticos.",
    "legal.privacy.s6.p2": "Para exercer seus direitos, entre em contato via e-mail em {email}. Responderemos em até 15 dias úteis.",
    "legal.privacy.s7.title": "7. Cookies",
    "legal.privacy.s7.p": "Utilizamos cookies essenciais (necessários para o funcionamento correto do carrinho e login) e cookies analíticos (somente com o seu consentimento prévio). Veja nossa {cookiesLink} para mais detalhes.",
    "legal.privacy.s8.title": "8. Retenção de dados",
    "legal.privacy.s8.p": "Mantemos seus dados pessoais apenas pelo tempo necessário para cumprir as finalidades desta política ou conforme exigido pela legislação aplicável (em geral, 5 anos para registros fiscais e contábeis). Contas inativas há mais de 2 anos poderão ser anonimizadas ou excluídas.",
    "legal.privacy.s9.title": "9. Segurança",
    "legal.privacy.s9.p": "Adotamos medidas técnicas e organizacionais avançadas para proteger suas informações, incluindo criptografia de navegação (HTTPS/SSL), autenticação segura com Firebase e controle estrito de acesso ao painel administrativo.",
    "legal.privacy.s10.title": "10. Alterações nesta política",
    "legal.privacy.s10.p": "Podemos atualizar esta política periodicamente para refletir melhorias em nossos processos. Alterações relevantes serão notificadas via e-mail ou por aviso em nosso site. A data de última atualização sempre estará indicada no topo desta página.",
    "legal.privacy.s11.title": "11. Contato",
    "legal.privacy.s11.p": "Para dúvidas sobre privacidade e proteção de dados:",
