    "legal.terms.s1.title": "1. Aceitação dos termos",
    "legal.terms.s1.p": "Ao acessar ou utilizar o site **nikkeybox.jp**, você concorda em cumprir estes Termos de Uso. Caso não concorde com qualquer disposição aqui contida, solicitamos que não continue a utilizar o site. Estes termos aplicam-se a todos os visitantes, clientes e usuários cadastrados.",
    "legal.terms.s2.title": "2. Sobre a NikkeyBox",
    "legal.terms.s2.p1": "A **{brand}** é uma loja online especializada em produtos originais importados do Japão (cosméticos, doces, papelaria, acessórios e outros), operada por **{contact}** a partir de **{address}**.",
    "legal.terms.s2.p2": "**Aviso de venda internacional:** todos os pedidos são enviados diretamente do Japão e estão sujeitos a fiscalização alfandegária, eventuais tributos de importação e taxas cobradas pelas autoridades do país de destino (como a Receita Federal do Brasil).",
    "legal.terms.s3.title": "3. Cadastro e conta",
    "legal.terms.s3.li1": "O usuário compromete-se a fornecer informações exatas, atualizadas e completas no momento do cadastro.",
    "legal.terms.s3.li2": "A guarda e o sigilo da senha de acesso são de responsabilidade exclusiva do usuário.",
    "legal.terms.s3.li3": "Menores de 18 anos devem obter autorização expressa dos pais ou responsáveis legais antes de efetuar compras.",
    "legal.terms.s3.li4": "Reservamo-nos o direito de suspender ou encerrar contas que apresentem atividades suspeitas, inconsistentes ou fraudulentas.",
    "legal.terms.s4.title": "4. Produtos e preços",
    "legal.terms.s4.li1": "Os preços podem ser exibidos na moeda selecionada pelo usuário (BRL, JPY ou EUR).",
    "legal.terms.s4.li2": "As imagens exibidas no site são meramente ilustrativas; pequenas variações na embalagem ou no design podem ocorrer por atualizações dos fabricantes no Japão.",
    "legal.terms.s4.li3": "Reservamo-nos o direito de alterar os preços dos produtos a qualquer momento, sem aviso prévio.",
    "legal.terms.s4.li4": "Em caso de erro crasso e evidente de precificação no sistema, o pedido poderá ser cancelado pela administração com o devido reembolso integral do valor pago.",
    "legal.terms.s5.title": "5. Pedidos e pagamento",
