    "prohibited.r1.name": "Medicamentos",
    "prohibited.r1.detail": "Uso pessoal: até 3 meses de tratamento. Necessita receita médica em inglês ou português. Máx. 10 unidades por item.",
    "prohibited.r2.name": "Suplementos alimentares",
    "prohibited.r2.detail": "Máx. 3 unidades por tipo. Deve estar na embalagem original com lista de ingredientes.",
    "prohibited.r3.name": "Baterias de lítio avulsas (sem dispositivo)",
    "prohibited.r3.detail": "Proibidas pela Japan Post. Baterias JÁ INSTALADAS em dispositivos são permitidas.",
    "prohibited.r4.name": "Aerossóis e sprays pressurizados",
    "prohibited.r4.detail": "Proibidos em EMS/Avião. Não disponível para envio.",
    "prohibited.r5.name": "Perfumes e produtos com álcool acima de 70%",
    "prohibited.r5.detail": "Via aérea: máx. 500ml por pacote. Deve ser declarado.",
    "prohibited.r6.name": "Plantas, sementes e bulbos",
    "prohibited.r6.detail": "Exige Certificado Fitossanitário (phytosanitary certificate) do MAPA do Japão.",
    "prohibited.r7.name": "Alimentos de origem animal (carne, laticínios)",
    "prohibited.r7.detail": "Exige inspeção veterinária e certificado sanitário. Geralmente bloqueado na aduana.",
    "prohibited.r8.name": "Óleos essenciais e inflamáveis",
    "prohibited.r8.detail": "Classificados como perigosos. Proibidos em via aérea. Marítimo requer documentação DGD.",
    "prohibited.r9.name": "Facas e objetos cortantes",
    "prohibited.r9.detail": "Permitidos se for uso culinário ou artístico. Réplicas de armas são proibidas.",
    "prohibited.r10.name": "Lasers e ponteiros laser",
    "prohibited.r10.detail": "Acima de 1mW pode ser retido na aduana brasileira.",
    "prohibited.a1.name": "Cosméticos",
    "prohibited.a1.detail": "Permitidos. Acima de R$3.000 (valor total do pacote) pode incidir imposto de importação de 20%.",
    "prohibited.a2.name": "Eletrônicos",
    "prohibited.a2.detail": "Permitidos. Declare o valor correto. Pacotes acima de US$50 podem ser taxados pela Receita Federal.",
    "prohibited.a3.name": "Alimentos industrializados (snacks, doces, chás)",
    "prohibited.a3.detail": "Permitidos se selados e na embalagem original. Declare como \"food/alimento\".",
    "prohibited.a4.name": "Brinquedos e action figures",
    "prohibited.a4.detail": "Permitidos. Declare valor real — subfaturamento pode causar apreensão.",
    "prohibited.a5.name": "Papelaria e canetas",
    "prohibited.a5.detail": "Sem restrições. Declare normalmente.",
    "prohibited.a6.name": "Roupas e vestuário",
    "prohibited.a6.detail": "Permitidos. Acima de 3 peças iguais pode ser considerado comercial.",
    "prohibited.a7.name": "Calçados",
    "prohibited.a7.detail": "Permitidos. Mais de 1 par igual pode ser questionado.",
    "prohibited.a8.name": "Produtos com pilhas AAA/AA incluídas",
    "prohibited.a8.detail": "Permitidos. Pilhas alcalinas comuns não são perigosas. Baterias de lítio devem estar instaladas.",
    "prohibited.a9.name": "Vinhos e bebidas alcoólicas",
    "prohibited.a9.detail": "Proibidos em EMS/avião. Não disponível para envio no momento.",
    "prohibited.a10.name": "Itens de alto valor (relógios, joias)",
    "prohibited.a10.detail": "Declare o valor real. Seguro recomendado. CN23 obrigatório.",
