    "videos.badge": "Unboxing de Clientes",
    "videos.title": "Opinião de Quem Recebeu",
    "videos.description": "Acompanhe vídeos simples de pessoas reais recebendo suas caixas, experimentando os snacks e testando a linha de cosméticos em suas casas.",
    "about.badge": "Quem Somos",
    "about.title": "Do Japão para o Mundo, com amor",
    "about.p1": "Nossa missão é aproximar você dos produtos japoneses que você ama. Gerenciamos nossos envios a partir de Tsu-shi, Mie, garantindo rapidez e embalagens ultra-seguras.",
    "about.p2": "Selecione e compre as principais novidades em cosméticos, papelaria estilosa, colecionáveis geeks de anime e deliciosos snacks importados com suporte completo em seu idioma.",
    "about.founded": "Fundação",
    "about.customers": "Clientes",
    "about.rating": "Avaliação",
    "aboutPage.badge": "Quem Somos",
    "aboutPage.hero.badge": "Sua Conexão Direta com o Japão",
    "aboutPage.hero.title": "Mais do que uma loja, somos uma ponte entre o Japão e você.",
    "aboutPage.hero.p1": "A NikkeyBox nasceu da paixão por conectar pessoas aos melhores produtos, tendências e experiências do Japão e da Coreia. Localizados em Tsu-shi, Mie, oferecemos compras personalizadas, redirecionamento de encomendas e envios internacionais com segurança, transparência e atendimento dedicado.",
    "aboutPage.hero.p2": "Selecionamos cuidadosamente cosméticos, produtos de skincare, alimentos, suplementos, itens exclusivos e lançamentos diretamente das principais lojas japonesas e coreanas, garantindo autenticidade, qualidade e confiança em cada pedido.",
    "aboutPage.hero.p3": "Nosso compromisso é tornar sua experiência simples e segura, acompanhando cada etapa do processo, desde a busca pelo produto ideal até a entrega em seu destino.",
    "aboutPage.hero.p4": "Acreditamos que a distância não deve ser um obstáculo para quem deseja ter acesso ao melhor que o Japão oferece.",
    "aboutPage.hero.tagline": "NikkeyBox — aproximando você da qualidade, inovação e cultura japonesa, onde quer que você esteja.",
    "aboutPage.title": "Sua Conexão Direta com o Japão",
    "aboutPage.description": "Somos apaixonados por aproximar a cultura de excelência e inovação do Japão aos clientes globais. Nosso centro logístico em Tsu-shi, Mie, atende envios domésticos e internacionais com segurança total.",
    "aboutPage.family": "Equipe NikkeyBox",
    "aboutPage.location": "Tsu-shi, Mie-ken, Japão",
    "aboutPage.kitchen": "Centro de Distribuição",
    "aboutPage.valuesTitle": "Nossos Valores",
    "aboutPage.valuesSubtitle": "O que nos move a cada dia para entregar os melhores produtos do Japão com segurança impecável.",
    "aboutPage.value1.title": "Originalidade",
    "aboutPage.value1.desc": "Trabalhamos estritamente com produtos oficiais e fornecedores licenciados no Japão.",
    "aboutPage.value2.title": "Qualidade Premium",
    "aboutPage.value2.desc": "Selecionamos apenas marcas consolidadas e recomendadas no exigente mercado japonês.",
    "aboutPage.value3.title": "Cuidado no Envio",
    "aboutPage.value3.desc": "Cada caixa é embalada com multicamadas de proteção térmica e contra impactos.",
    "aboutPage.value4.title": "Excelência Logística",
    "aboutPage.value4.desc": "Despachamos em tempo recorde e oferecemos rastreamento detalhado até seu endereço.",
    "aboutPage.journeyTitle": "Nossa Jornada",
    "aboutPage.journeySubtitle": "De Mie para o mundo.",
    "aboutPage.timeline.2018.title": "O Começo",
