    "shippingPage.faqTitle": "Perguntas Frequentes",
    "shippingPage.faq1.q": "Quanto tempo demora a entrega?",
    "shippingPage.faq1.a": "O tempo varia de acordo com a sua localização. Para regiões próximas a Mie (Kansai/Chubu), a entrega leva de 1 a 2 dias úteis. Para regiões mais distantes como Hokkaido e Okinawa, pode levar de 3 a 4 dias úteis.",
    "shippingPage.faq2.q": "Como são embalados os produtos?",
    "shippingPage.faq2.a": "Utilizamos caixas de 60cm para pedidos menores (até 8 potes pequenos) e caixas de 80cm para pedidos maiores. Cada pote é cuidadosamente protegido com material de enchimento para garantir que chegue em perfeitas condições.",
    "shippingPage.faq3.q": "Posso escolher a transportadora?",
