    "shippingPage.faq4.q": "O que acontece se o produto chegar danificado?",
    "shippingPage.faq4.a": "Garantimos a qualidade dos nossos produtos. Caso ocorra algum problema durante o transporte, entre em contato conosco imediatamente e providenciaremos a reposição ou reembolso.",
