    "product.biore.name": "Protetor Solar Bioré UV Aqua Rich SPF 50+",
    "product.biore.desc": "Líder absoluto de vendas no Japão! Sua fórmula revolucionária com tecnologia Micro Defense garante altíssima proteção UVA/UVB invisível, penetrando nas menores frestas da pele. Textura gel à base de água super leve, de rápida absorção e com toque refrescante. Resistente à água e ao suor, ideal para o clima diário do Brasil.",
    "product.biore.flavor": "Aqua Rich Gel",
    "product.matchakitkat.name": "KitKat Matcha Green Tea (Edição Japão)",
    "product.matchakitkat.desc": "O autêntico e inconfundível wafer coberto com chocolate branco blendado com chá verde Matcha premium de Uji, Kyoto. Perfeitamente equilibrado entre o amargor sutil do chá verde e a doçura do chocolate. Edição exclusiva importada diretamente das fábricas do Japão.",
    "product.matchakitkat.flavor": "Matcha de Uji",
    "product.luffy.name": "Action Figure Monkey D. Luffy - Gear 5 (Sun God)",
    "product.luffy.desc": "Estátua colecionável de altíssima fidelidade e acabamento. Captura a transformação lendária Gear 5 (Deus do Sol Nika) de Luffy com sua pose cômica e cabelos brancos flutuantes. Pintura detalhada anti-desbotamento e PVC reforçado. Versão Deluxe acompanha base detalhada e iluminação LED integrada.",
    "product.luffy.flavor": "Luffy Deus do Sol Nika",
    "product.gatinho.name": "Luminária Kawaii Gatinho LED de Silicone Touch",
    "product.gatinho.desc": "Luminária de cabeceira em silicone premium ultra macio e flexível, totalmente livre de BPA. Sensor de toque integrado para alternar facilmente entre 7 cores de iluminação ou modo transição suave. Recarregável via USB com bateria de alta capacidade, garantindo até 15 horas de luz aconchegante.",
    "product.gatinho.flavor": "Gatinho Dormindo",
    "product.canetassan.name": "Canetas Gel Sakura Gelly Roll - Set de 10 Cores",
    "product.canetassan.desc": "As canetas em gel originais fabricadas no Japão. Tecnologia pioneira de tinta em gel pigmentada de fluxo ultra suave, resistente à água e ao desbotamento. Ponta esferográfica de alta precisão que desliza no papel. Estojo exclusivo contendo cores clássicas e metálicas vibrantes.",
    "product.canetassan.flavor": "Edição Gel Clássica",
    "product.organizador.name": "Organizador Modular Acrílico Cristalino (Estilo Muji)",
    "product.organizador.desc": "Organizador com divisórias e gavetas modulares fabricado em acrílico de alta densidade com transparência óptica perfeita. Cantos polidos e estrutura robusta de design japonês minimalista. A solução elegante e durável para arrumar cosméticos, joias ou itens de escritório.",
    "product.organizador.flavor": "Acrílico Minimalista",
    "product.chaverde.name": "Chá Verde Japonês Sencha de Uji - Folhas Soltas",
    "product.chaverde.desc": "Chá verde Sencha de colheita premium colhido na famosa província de Uji, Kyoto. Cultivado à sombra para realçar o sabor umami e manter a cor verde brilhante. Notas herbais complexas, aroma refrescante e rico em L-teanina e antioxidantes naturais para sua saúde.",
    "product.chaverde.flavor": "Sencha Orgânico",
    "hero.badge.japan": "Produtos Exclusivos do Japão 🌸",
    "hero.title.1.japan": "Sua loja de",
    "hero.title.highlight.japan": "importados",
    "hero.title.2.japan": "favoritos no Japão",
    "hero.description.japan": "Os melhores cosméticos, papelaria, acessórios e doces selecionados e enviados diretamente do nosso centro em Mie para todo o Japão com frete expresso local.",
    "hero.cta.products.japan": "Ver Produtos",
    "hero.cta.story.japan": "Calculadora de Frete",
    "hero.badge.brazil": "Produtos Importados do Japão 🌸",
    "hero.title.1.brazil": "A sua loja de",
    "hero.title.highlight.brazil": "importados",
    "hero.title.2.brazil": "japoneses",
    "hero.description.brazil": "Os melhores cosméticos, papelaria, acessórios e doces direto do Japão para você, com frete seguro. Veja a aba \"Como Funciona\" e entenda todo o processo, do pedido à entrega.",
    "hero.cta.products.brazil": "Explorar Loja",
    "hero.cta.story.brazil": "Ver Ofertas",
    "about.badge.japan": "Quem Somos",
    "about.title.japan": "Conectando o Melhor do Japão",
    "about.p1.japan": "Somos apaixonados por selecionar o melhor do Japão. Nosso centro de distribuição em Tsu-shi, Mie, gerencia uma curadoria exclusiva de cosméticos premium, papelaria de precisão, doces de Uji e colecionáveis geeks.",
    "about.p2.japan": "Cada pedido é conferido meticulosamente e embalado com proteção reforçada contra impactos, garantindo uma experiência de unboxing premium para todos os nossos clientes em território japonês.",
    "about.badge.brazil": "Quem Somos",
    "about.title.brazil": "NikkeyBox: Do Japão para o Brasil",
