    "how.j1.title": "You place the order",
    "how.j1.desc": "Choose products in the catalog and complete your cart. Can be a ready product or a custom \"Place Your Order\".",
    "how.j2.title": "Payment",
    "how.j2.desc": "Pay via PIX or Wise (Brazil), PayPay (Japan) or Wise (international). We start preparing only after payment confirmation.",
    "how.j3.title": "Preparation in Mie",
    "how.j3.desc": "We carefully pick and pack everything in our Japan store, with extra protection for the journey.",
    "how.j4.title": "Air / sea shipping",
    "how.j4.desc": "The package travels from Japan to your country via the chosen carrier (EMS, Correios, Yamato, sea...).",
    "how.j5.title": "Customs & taxes",
    "how.j5.desc": "On arrival, customs inspects the package. If there is tax, you receive a notification and pay online BEFORE release — never in cash to the postal worker.",
    "how.j6.title": "Carrier delivers",
    "how.j6.desc": "Your country's postal service handles the last mile. You track everything with the tracking code.",
    "how.j7.title": "Arrives at your door 🎉",
    "how.j7.desc": "You receive at your door (or pick up at the post office if you prefer). Done — a piece of Japan has arrived!",
    "how.pay.pix.tag": "Brazil 🇧🇷",
