    "how.pay.pix.s4": "Payment is identified automatically and your order enters preparation.",
    "how.pk1.t": "Home delivery",
    "how.pk1.d": "After clearance (and tax paid online, if any), the carrier delivers to your address. Taxes are always paid in advance via app — never in cash at the door.",
    "how.pk2.t": "Pick up at post office",
    "how.pk2.d": "If no one is home, the package stays at a nearby post office for pickup with ID.",
    "how.pk3.t": "Inspect and sign",
    "how.pk3.d": "Check the packaging upon delivery. In case of damage, document it and let us know — we help with the carrier.",
