    "how.tax.br.note": "Correios only delivers — the Federal Revenue is the taxing authority. You're notified by the Correios app/email/SMS and pay online (Pix, card or boleto) BEFORE the package is released. Never pay in cash to the postal worker. ⚠️ Beware of fake links: always confirm in the official app or at correios.com.br.",
