    "how.biz.s1.t": "Radar / Siscomex Registration",
    "how.biz.s1.d": "The company needs a Radar (Importer Registration) approved by the Federal Revenue to operate in Siscomex — Brazil's official foreign trade system.",
    "how.biz.s2.t": "Customs Broker",
    "how.biz.s2.d": "A customs broker registers the operation and handles documentation. For large volumes/values, this is practically mandatory.",
    "how.biz.s3.t": "Import Declaration (DI)",
    "how.biz.s3.d": "Formal imports are registered via Import Declaration (DI) in Siscomex, with the NCM tax classification of each product and the customs value.",
    "how.biz.s4.t": "Applicable Taxes and Fees",
    "how.biz.s4.d": "Taxes, fees and customs requirements are defined by the competent authorities according to the shipment, destination and each product's NCM classification. Amounts and processing times are not guaranteed.",
