    "ui.correiosApp": "Correios app",
    "how.biz.intro": "For commercial goods, competent authorities define when **formal import procedures** apply and what requirements must be met, based on the shipment and destination:",
    "how.biz.note": "⚠️ Notifications and payments do **not** come through the Correios app as in regular purchases — everything goes through Siscomex and the customs broker. Timelines and costs also differ.",
