    "ui.ps.badge": "Exclusive Personal Shopper Service in Japan",
    "ui.ps.title1": "Can't find what you're looking for?",
    "ui.ps.title2": "We buy any product in Japan for you!",
    "ui.ps.desc": "Send the name, photo or link of the item you want (new cosmetics, limited sweets, collectibles or electronics). We get a quote from Japanese stores and ship straight to your home.",
    "ui.ps.authentic": "100% Authentic",
