    "prohibited.p1.name": "Firearms, ammunition and replicas",
    "prohibited.p1.detail": "Any type, including parts and accessories",
    "prohibited.p2.name": "Explosives, fireworks and flares",
    "prohibited.p3.name": "Illegal drugs and narcotics",
    "prohibited.p3.detail": "Including cannabis seeds",
    "prohibited.p4.name": "Child sexual abuse material",
    "prohibited.p5.name": "Live animals",
    "prohibited.p6.name": "Human remains",
    "prohibited.p7.name": "Counterfeit money and forged documents",
    "prohibited.p8.name": "Smuggled or pirated goods",
    "prohibited.p9.name": "Radioactive substances",
    "prohibited.p10.name": "Raw soil and earth",
    "prohibited.p10.detail": "Phytosanitary risk",
    "prohibited.r1.name": "Medicines",
    "prohibited.r1.detail": "Personal use: up to 3 months of treatment. Requires a medical prescription in English or Portuguese. Max. 10 units per item.",
    "prohibited.r2.name": "Dietary supplements",
    "prohibited.r2.detail": "Max. 3 units per type. Must be in the original packaging with the ingredient list.",
    "prohibited.r3.name": "Loose lithium batteries (without a device)",
    "prohibited.r3.detail": "Prohibited by Japan Post. Batteries ALREADY INSTALLED in a device are allowed.",
    "prohibited.r4.name": "Aerosols and pressurized sprays",
    "prohibited.r4.detail": "Prohibited by EMS/air. Not available for shipping.",
    "prohibited.r5.name": "Perfumes and products with more than 70% alcohol",
    "prohibited.r5.detail": "By air: max. 500ml per package. Must be declared.",
    "prohibited.r6.name": "Plants, seeds and bulbs",
    "prohibited.r6.detail": "Requires a phytosanitary certificate (phytosanitary certificate) from Japan's MAFF.",
    "prohibited.r7.name": "Animal-origin foods (meat, dairy)",
    "prohibited.r7.detail": "Requires veterinary inspection and a health certificate. Usually blocked at customs.",
    "prohibited.r8.name": "Essential oils and flammable items",
    "prohibited.r8.detail": "Classified as dangerous goods. Prohibited by air. Sea shipping requires DGD documentation.",
    "prohibited.r9.name": "Knives and sharp objects",
    "prohibited.r9.detail": "Allowed for culinary or artistic use. Weapon replicas are prohibited.",
    "prohibited.r10.name": "Lasers and laser pointers",
    "prohibited.r10.detail": "Above 1mW may be held at Brazilian customs.",
    "prohibited.a1.name": "Cosmetics",
    "prohibited.a1.detail": "Allowed. Above R$3,000 (total package value) a 20% import tax may apply.",
    "prohibited.a2.name": "Electronics",
    "prohibited.a2.detail": "Allowed. Declare the correct value. Packages above US$50 may be taxed by the Receita Federal.",
    "prohibited.a3.name": "Packaged foods (snacks, sweets, teas)",
    "prohibited.a3.detail": "Allowed if sealed and in the original packaging. Declare as \"food/alimento\".",
    "prohibited.a4.name": "Toys and action figures",
    "prohibited.a4.detail": "Allowed. Declare the real value — under-declaring may lead to seizure.",
    "prohibited.a5.name": "Stationery and pens",
    "prohibited.a5.detail": "No restrictions. Declare normally.",
    "prohibited.a6.name": "Clothing and apparel",
    "prohibited.a6.detail": "Allowed. More than 3 identical pieces may be considered commercial.",
    "prohibited.a7.name": "Footwear",
    "prohibited.a7.detail": "Allowed. More than 1 identical pair may be questioned.",
    "prohibited.a8.name": "Products with AAA/AA batteries included",
    "prohibited.a8.detail": "Allowed. Standard alkaline batteries are not dangerous. Lithium batteries must be installed in the device.",
    "prohibited.a9.name": "Wine and alcoholic beverages",
    "prohibited.a9.detail": "Prohibited by EMS/air. Not available for shipping at the moment.",
    "prohibited.a10.name": "High-value items (watches, jewelry)",
    "prohibited.a10.detail": "Declare the real value. Insurance recommended. CN23 required.",
