    "videos.badge": "Customer Unboxings",
    "videos.title": "What Our Customers Say",
    "videos.description": "Watch simple, real videos of everyday people receiving their packages, trying out snacks, and testing cosmetics in their homes.",
    "about.badge": "About Us",
    "about.title": "From Japan to the World, with love",
    "about.p1": "Our mission is to bring you closer to the Japanese products you love. We manage all shipments from Tsu-shi, Mie, ensuring speed and ultra-secure packaging.",
    "about.p2": "Browse and buy top trends in cosmetics, stylish stationery, geek anime collectibles, and delicious imported snacks with complete support in your language.",
    "about.founded": "Founded",
    "about.customers": "Customers",
    "about.rating": "Rating",
    "aboutPage.badge": "About Us",
    "aboutPage.hero.badge": "Your Direct Connection with Japan",
    "aboutPage.hero.title": "More than a store — we are a bridge between Japan and you.",
    "aboutPage.hero.p1": "NikkeyBox was born from the passion for connecting people to the best products, trends and experiences from Japan and Korea. Based in Tsu-shi, Mie, we offer personalized shopping, parcel forwarding and international shipping with security, transparency and dedicated support.",
    "aboutPage.hero.p2": "We carefully select cosmetics, skincare products, food, supplements, exclusive items and new releases directly from the leading Japanese and Korean stores, ensuring authenticity, quality and trust in every order.",
    "aboutPage.hero.p3": "Our commitment is to make your experience simple and safe, accompanying every step of the process — from finding the perfect product to delivery at your door.",
    "aboutPage.hero.p4": "We believe distance should never be an obstacle for those who want access to the best Japan has to offer.",
    "aboutPage.hero.tagline": "NikkeyBox — bringing you closer to Japanese quality, innovation and culture, wherever you are.",
    "aboutPage.title": "Your Direct Connection with Japan",
    "aboutPage.description": "We are passionate about bridging Japan's culture of excellence and innovation to global customers. Our logistics hub in Tsu-shi, Mie, serves domestic and international shipments with total security.",
