    "shippingPage.faqTitle": "Frequently Asked Questions",
    "shippingPage.faq1.q": "How long does delivery take?",
    "shippingPage.faq1.a": "The time varies according to your location. For regions close to Mie (Kansai/Chubu), delivery takes 1 to 2 business days. For more distant regions like Hokkaido and Okinawa, it may take 3 to 4 business days.",
    "shippingPage.faq2.q": "How are products packaged?",
    "shippingPage.faq2.a": "We use 60cm boxes for smaller orders (up to 8 small jars) and 80cm boxes for larger orders. Each jar is carefully protected with padding material to ensure it arrives in perfect condition.",
    "shippingPage.faq3.q": "Can I choose the carrier?",
    "shippingPage.faq3.a": "Yes! We show all available options with their respective prices so you can choose the one that best suits your needs.",
    "shippingPage.faq4.q": "What happens if the product arrives damaged?",
    "shippingPage.faq4.a": "We guarantee the quality of our products. If any issue occurs during transport, contact us immediately and we will arrange a replacement or refund.",
