    "product.biore.name": "Bioré UV Aqua Rich Sunscreen SPF 50+",
    "product.biore.desc": "The absolute best-seller in Japan! Its revolutionary Micro Defense technology ensures ultra-high invisible UVA/UVB protection, covering even micro-crevices. Extremely light water-like gel texture, fast absorption, and a refreshing feel. Water and sweat resistant.",
    "product.biore.flavor": "Aqua Rich Gel",
    "product.matchakitkat.name": "KitKat Matcha Green Tea (Japan Edition)",
    "product.matchakitkat.desc": "The authentic, unmistakable wafer covered in white chocolate blended with premium Matcha green tea from Uji, Kyoto. Perfectly balanced between subtle tea bitterness and chocolate sweetness. Imported directly from Japan.",
    "product.matchakitkat.flavor": "Uji Matcha",
    "product.luffy.name": "Monkey D. Luffy Gear 5 (Sun God Nika) Action Figure",
    "product.luffy.desc": "Highly detailed collector's action figure of Luffy's legendary Gear 5 (Sun God Nika) transformation. Features detailed anti-fade paint and reinforced PVC. Deluxe version includes a detailed base and integrated LED lighting.",
    "product.luffy.flavor": "Luffy Sun God Nika",
    "product.gatinho.name": "Kawaii Kitty LED Touch Silicone Night Light",
    "product.gatinho.desc": "Premium soft silicone night light, fully BPA-free. Sensitive touch control allows easy switching between 7 colors or a smooth breathing mode. USB rechargeable with a built-in battery lasting up to 15 hours.",
    "product.gatinho.flavor": "Sleeping Kitty",
    "product.canetassan.name": "Sakura Gelly Roll Gel Pens - 10 Color Set",
    "product.canetassan.desc": "The original gel pens made in Japan. Pioneering gel ink technology with ultra-smooth flow, waterproof, and fade-resistant. High-precision ballpoint that glides on paper. Set features classic and vibrant metallic colors.",
    "product.canetassan.flavor": "Classic Gel Edition",
    "product.organizador.name": "Crystal Acrylic Modular Organizer (Muji Style)",
    "product.organizador.desc": "Minimalist modular organizer made of high-density crystal acrylic with perfect clarity. Polished corners and durable build. Ideal for organizing cosmetics, jewelry, or office supplies.",
    "product.organizador.flavor": "Minimalist Acrylic",
    "product.chaverde.name": "Japanese Sencha Green Tea from Uji - Loose Leaves",
    "product.chaverde.desc": "Premium loose-leaf Sencha green tea from the famous Uji region in Kyoto. Grown under shade to enhance umami and preserve the bright green color. Complex herbal notes, refreshing aroma, rich in antioxidants and L-theanine.",
    "product.chaverde.flavor": "Organic Sencha",
