    "aboutPage.hero.title": "単なる店舗ではなく、日本とあなたをつなぐ架け橋です。",
    "aboutPage.hero.p1": "NikkeyBoxは、日本と韓国の最高の商品、トレンド、体験を世界の人々に届けたいという情熱から生まれました。三重県津市を拠点に、パーソナライズされたショッピング、荷物の転送、そして安全・透明・丁寧な国際発送サービスを提供しています。",
    "aboutPage.hero.p2": "コスメ、スキンケア、食品、サプリメント、限定アイテム、新発売商品を日本・韓国の主要店舗から厳選し、すべての注文において本物保証・品質・信頼をお約束します。",
    "aboutPage.hero.p3": "理想の商品探しからお手元への配送まで、すべてのステップに寄り添い、シンプルで安心なお買い物体験を提供することが私たちのコミットメントです。",
    "aboutPage.hero.p4": "日本の最高のものを手に入れたいと思う方々にとって、距離は障壁であってはならないと私たちは信じています。",
    "aboutPage.hero.tagline": "NikkeyBox — 品質・革新・日本文化を、どこにいてもあなたのもとへ。",
    "aboutPage.title": "日本と世界をつなぐ架け橋",
