    "product.biore.name": "ビオレ UV アクアリッチ ウォータリーエッセンス SPF 50+",
    "product.biore.desc": "日本で大人気の日焼け止め！ミクロディフェンス処方で、肌の微細な隙間まで均一にカバーし、目に見えないUVA/UVBから強力に保護します。水のように軽いジェル質感で、素早く吸収され、爽やかな使い心地。水・汗に強いタイプ。",
    "product.biore.flavor": "アクアリッチジェル",
    "product.matchakitkat.name": "キットカット ミニ 宇治抹茶（日本限定）",
    "product.matchakitkat.desc": "京都宇治産の厳選抹茶を使用した、ホワイトチョコレートブレンドでコーティングされたサクサクのウエハース。抹茶ならではのほのかな苦味と、チョコレートの甘さが絶妙に調和した一品。",
    "product.matchakitkat.flavor": "宇治抹茶",
    "product.luffy.name": "モンキー・D・ルフィ ギア5（太陽の神ニカ）フィギュア",
    "product.luffy.desc": "ルフィの伝説的な変身「ギア5（太陽の神ニカ）」を忠実に再現したハイクオリティコレクターズフィギュア。細部まで施された塗装と強化PVC製。デラックス版には専用台座とLEDライトアップ機能が付属。",
    "product.luffy.flavor": "ルフィ 太陽の神ニカ",
    "product.gatinho.name": "かわいい子猫 LED タッチセンサー シリコンナイトライト",
    "product.gatinho.desc": "BPAフリーの高品質で柔らかいシリコン製ナイトライト。タップするだけで7色切り替えやゆっくり変化する呼吸モードを楽しめます。USB充電式で最大15時間点灯可能。",
    "product.gatinho.flavor": "眠る子猫",
    "product.canetassan.name": "サクラ ゲリーロール ゲルインキボールペン 10色セット",
    "product.canetassan.desc": "日本製のオリジナルゲルインキペン。なめらかな書き味と、水・光に強い顔料インキを採用。クラシックカラーと輝くメタリックカラーの10本セット。",
    "product.canetassan.flavor": "クラシックゲル版",
    "product.organizador.name": "アクリル スタッキングチェスト（無印良品風）",
    "product.organizador.desc": "高い透明度を誇る高密度アクリル製ミニマルオーガナイザー。角は磨き加工が施され、耐久性も抜群。化粧品やジュエリー、文房具の整理に最適です。",
    "product.organizador.flavor": "ミニマルアクリル",
    "product.chaverde.name": "京都宇治産 煎茶（茶葉・リーフ）",
    "product.chaverde.desc": "お茶の名産地、京都宇治産のプレミアム煎茶。旨味を引き出し、美しい緑色を保つために被覆栽培されました。煎茶本来の爽やかな香りと豊かな味わい、カテキンやL-テアニンなどの健康成分も豊富です。",
    "product.chaverde.flavor": "有機煎茶",
