    "about.badge.japan": "私たちについて",
    "about.title.japan": "日本から世界へ、愛を込めて",
    "about.p1.japan": "日本の優れた製品を世界中のファンにお届けすることに情熱を注いでいます。三重県津市にある配送センターから、迅速で安全な梱包・発送を行っています。",
    "about.p2.japan": "コスメ、文房具、キャラクターフィギュア、厳選された和菓子などを、お客様の言語でのサポートとともに、安心してお買い求めいただけます。",
