    "about.title.brazil": "NikkeyBox：日本からブラジルへ",
    "about.p1.brazil": "私たちの使命は、日本の市場から最高の商品と独占的なニュースを皆様にお届けすることです。高品質の化粧品、コレクターズアイテム、お菓子、文房具を厳選してお届けします。",
    "about.p2.brazil": "三重県津市に物流センターを構え、細心の注意と強化梱包で全注文を準備・発送します。追跡コード付きの安心の国際配送を保証します。",
